const BREAKPOINTS = [['xs',0],['sm',576],['md',768],['lg',992],['xl',1200],['xxl',1400]];
function breakpointOf(width) {
  let name = 'xs';
  for (const [n, min] of BREAKPOINTS) if (width >= min) name = n;
  return name;
}
for (const w of [375, 600, 800, 1024, 1440]) {
  console.log(w + 'px -> ' + breakpointOf(w));
}
